/**
 * The hero of a store: a badge, the heading, a lead, one or two actions and three store promises. The overlay
 * layout puts a picture beside the text with an offer card floating on it; the backdrop layout puts the text
 * over a faint picture. Axes: layout (overlay, backdrop), mediaSide, tone.
 */
import { For, type JSX } from "solid-js";
import { Box } from "../primitives/box/box";
import { Grid } from "../primitives/grid/grid";
import { Group } from "../primitives/group/group";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { ActionGroup } from "../components/action-group";
import { Backdrop } from "../components/backdrop";
import { OfferMedia } from "../components/offer-media";
import { SectionFrame } from "../components/section-frame";
import type { OfferCard } from "./store-hero.types";
import type { Feature } from "./feature-grid.types";
import type { LinkActions } from "./error-page.types";

export type StoreHeroProps = {
  id: string;
  title: string;
  lead?: string;
  badge?: string;
  level?: 1 | 2;
  actions: LinkActions;
  perks: Feature[];
  card: OfferCard;
  layout?: "overlay" | "backdrop";
  mediaSide?: "end" | "start";
  tone?: "default" | "muted";
  landmarkLabel?: string;
};

export function StoreHero({
  id,
  title,
  lead = "",
  badge = "",
  level = 1,
  actions,
  perks,
  card,
  layout = "overlay",
  mediaSide = "end",
  tone = "default",
  landmarkLabel,
}: StoreHeroProps) {
  return (
    <>
      {((layout as string) === "backdrop") ? (
        <SectionFrame
          id={id}
          title={title}
          lead={lead}
          heading={{ badge, level }}
          tone={tone}
          density="roomy"
          measure="3xl"
          class={(("image" === "image") ? "relative isolate overflow-hidden" : "")}
          landmarkLabel={landmarkLabel}
        >
          <Backdrop kind="image" alt={title} />
          <ActionGroup
            primary={actions.cta}
            primaryHref={actions.href}
            secondary={((actions.mode === "two") ? actions.secondary : undefined)}
            secondaryHref={actions.secondaryHref}
          />
          <Grid cols="1-3" class="gap-4" data-testid="perks">
            <For each={perks ?? []}>{(p, iOf) => { const i = iOf(); return (
              <>
                {(i < 3) ? (
                  <Group gap="4" align="start" data-testid="perk">
                    <Box class="flex size-10 shrink-0 items-center justify-center rounded bg-muted">
                      <LucideIcon name={p.icon} size={20} />
                    </Box>
                    <Stack gap="0">
                      <Text size="sm" weight="semibold">
                        {p.title}
                      </Text>
                      <Text size="xs" class="text-muted-foreground">
                        {p.text}
                      </Text>
                    </Stack>
                  </Group>
                ) : null}
              </>
            ); }}</For>
          </Grid>
        </SectionFrame>
      ) : (
        <SectionFrame
          id={id}
          title={title}
          lead={lead}
          heading={{ badge, level }}
          layout="split"
          media={{ show: true, side: mediaSide }}
          tone={tone}
          landmarkLabel={landmarkLabel}
          aside={(
            <OfferMedia alt={title} card={card} />
          )}
        >
          <ActionGroup
            primary={actions.cta}
            primaryHref={actions.href}
            secondary={((actions.mode === "two") ? actions.secondary : undefined)}
            secondaryHref={actions.secondaryHref}
          />
          <Grid cols="1-3" class="gap-4" data-testid="perks">
            <For each={perks ?? []}>{(p, iOf) => { const i = iOf(); return (
              <>
                {(i < 3) ? (
                  <Group gap="4" align="start" data-testid="perk">
                    <Box class="flex size-10 shrink-0 items-center justify-center rounded bg-muted">
                      <LucideIcon name={p.icon} size={20} />
                    </Box>
                    <Stack gap="0">
                      <Text size="sm" weight="semibold">
                        {p.title}
                      </Text>
                      <Text size="xs" class="text-muted-foreground">
                        {p.text}
                      </Text>
                    </Stack>
                  </Group>
                ) : null}
              </>
            ); }}</For>
          </Grid>
        </SectionFrame>
      )}
    </>
  );
}

